mapper.sql:
p.published = 'Y'
AND (LOWER(NVL(pi.title, p.title)) LIKE LOWER(#{pattern}) ESCAPE '!'
  OR LOWER(NVL(pi.summary, p.summary)) LIKE LOWER(#{pattern}) ESCAPE '!')
AND p.situation = #{situation}
AND p.phase_code = #{phase}

JL_PROCEDURE p JOIN JL_REGION r ON r.id = p.region_id
JOIN JL_CATEGORY c ON c.id = p.category_id
LEFT JOIN JL_PROCEDURE_I18N pi ON pi.procedure_id = p.id AND pi.language_code = #{language}
